    default String formatLocality(Owner owner) {
        if (owner == null) {
            return null;
        }
        String code = owner.getCustomerCode();
        if (code != null) {
            int hyphen = code.indexOf('-');
            return hyphen >= 0 ? code.substring(0, hyphen) : code;
