250	     * the first eight upper-case hex characters of the SHA-256 of the owner's normalized telephone
251	     * concatenated with its last name (e.g. {@code NSW-3F5A9C2E}). The identity carries no sequence
252	     * number, so it depends only on the owner's own postcode, telephone and last name.
253	     */
254	    private String generateCustomerCode(Owner owner) {
255	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
256	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
257	        return Regions.forPostcode(owner.getPostcode()) + "-" + hash8(telephone + lastName);
258	    }
