260	    /**
261	     * The first eight upper-case hex characters (the first four bytes) of the SHA-256 of
262	     * {@code value}, the {@code HASH8} segment of a {@code customerCode}.
263	     */
264	    private static String hash8(String value) {
265	        try {
266	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
267	            StringBuilder sb = new StringBuilder(8);
268	            for (int i = 0; i < 4; i++) {
269	                sb.append(String.format("%02X", digest[i]));
270	            }
271	            return sb.toString();
272	        }
273	        catch (NoSuchAlgorithmException e) {
274	            throw new IllegalStateException("SHA-256 not available", e);
275	        }
