286	    public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
287	        String normalizedLastName = normalizeForComparison(lastName);
288	        String normalizedAddress = normalizeForComparison(address);
289	        if (normalizedLastName == null || normalizedAddress == null) {
290	            return false;
291	        }
292	        return ownerRepository.findAll().stream()
293	            .anyMatch(existing -> inHousehold(existing, normalizedLastName, normalizedAddress));
294	    }
295	
296	    /**
297	     * Canonicalize a free-text value for equality comparison: trim, collapse every run of
298	     * whitespace to a single space and lower-case the result, so values that differ only in
299	     * letter case or incidental whitespace are treated as equal. Shared by the household
300	     * (last name / address) and per-city matching rules.
301	     */
302	    private String normalizeForComparison(String value) {
303	        if (value == null) {
304	            return null;
305	        }
306	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
307	    }
308	
309	    /**
310	     * Single definition of household membership: an owner belongs to the household identified by
311	     * the given already-normalized last name and address when its own normalized last name and
312	     * address match. Keeping this in one place means the household-equality rule is changed once.
313	     */
314	    private boolean inHousehold(Owner existing, String normalizedLastName, String normalizedAddress) {
315	        return normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
316	            && normalizedAddress.equals(normalizeForComparison(existing.getAddress()));
317	    }
