330	        String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
331	        owner.setHouseholdId(householdId);
332	        String normalizedLastName = normalizeForComparison(owner.getLastName());
333	        String normalizedAddress = normalizeForComparison(owner.getAddress());
334	        if (normalizedLastName != null && normalizedAddress != null) {
335	            // Back-fill existing members of the household so the joining owner and the
336	            // owner(s) already at the address share the same stable identifier.
337	            for (Owner existing : ownerRepository.findAll()) {
338	                if (existing.getHouseholdId() == null
339	                    && inHousehold(existing, normalizedLastName, normalizedAddress)) {
340	                    existing.setHouseholdId(householdId);
341	                    ownerRepository.save(existing);
342	                }
343	            }
344	        }
345	        return householdId;
346	    }
