348	    /**
349	     * Derive a stable household identifier from the normalized last name and address, so that
350	     * every owner sharing a household (same last name and address, compared case-insensitively
351	     * with internal whitespace collapsed) maps to the same value. The identifier is the first
352	     * eight upper-case hex characters of the SHA-256 of {@code <lastName>|<address>}, prefixed
353	     * with {@code 'H-'} (e.g. {@code H-3F5A9C2E}).
354	     */
355	    private String generateHouseholdId(String lastName, String address) {
356	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
357	        try {
358	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
359	            StringBuilder sb = new StringBuilder("H-");
360	            for (int i = 0; i < 4; i++) {
361	                sb.append(String.format("%02X", digest[i]));
362	            }
363	            return sb.toString();
364	        }
365	        catch (NoSuchAlgorithmException e) {
366	            throw new IllegalStateException("SHA-256 not available", e);
367	        }
368	    }
