418	        try {
419	            return supplier.get();
420	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
421	            // Just ignore not found exceptions for Jdbc/Jpa realization
422	            return null;
423	        }
424	    }
